    public HotWordGroupController(HotWordGroupService hotWordGroupService) {
        this.hotWordGroupService = hotWordGroupService;
    }

    @PostMapping
    public ApiResponse<HotWordGroup> create(@RequestBody CreateGroupRequest request, Authentication authentication) {
